-- Sync master catalog into Unified Graph Nodes
INSERT OR IGNORE INTO graph_nodes (id, node_type, props_json, valid_from, valid_to, txn_from, txn_to)
SELECT
    id,
    CASE WHEN entity_type = 'vendor' THEN 'VENDOR' WHEN entity_type = 'client' THEN 'CLIENT' ELSE 'ENTITY' END,
    json_object('name', name, 'contact_person', contact_person, 'phone', phone, 'email', email, 'gstin', gstin, 'address', address),
    created_at,
    NULL,
    created_at,
    NULL
FROM master_entities;

INSERT OR IGNORE INTO graph_nodes (id, node_type, props_json, valid_from, valid_to, txn_from, txn_to)
SELECT
    id,
    UPPER(category),
    json_object('code', code, 'display_name', display_name, 'meta', json(meta_json)),
    created_at,
    NULL,
    created_at,
    NULL
FROM master_items;
